  json: {
    money,
    ollamaBody: {
      model: MODEL,
      stream: false,
      keep_alive: KEEP_ALIVE,
      format: schema,
      options: { ...OLLAMA_OPTIONS, temperature: 0.9, num_predict: 320 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

